html:
{# ============================
  HEADER CONTEXT SETUP
============================= #}

{%- set driver_doc = frappe.get_doc('Driver', doc.driver) -%}
{%- set staff_doc = frappe.get_doc('Staff', driver_doc.staff) if driver_doc.staff else None -%}
{%- set company_name = staff_doc.company_name if staff_doc else doc.company -%}
{%- set company = frappe.get_doc('Company', company_name) -%}

{# --- Fetch Child Documents Dynamically --- #}

{%- set company_docs = frappe.get_all('Company Documents', filters={'parent': company.name}, fields=['document_type', 'document_no', 'expiry_date']) -%}
{%- set cr_doc = (company_docs | selectattr('document_type', 'equalto', 'CR No') | list | first) -%}
{%- set reg_doc = (company_docs | selectattr('document_type', 'equalto', 'Registration No') | list | first) -%}

{%- set driver_docs = frappe.get_all('Driver Documents', filters={'parent': driver_doc.name}, fields=['document_type', 'document_no', 'expiry_date']) -%}
{%- set license_doc = (driver_docs | selectattr('document_type', 'equalto', 'Driving License') | list | first) -%}
{%- set iqama_doc = (driver_docs | selectattr('document_type', 'equalto', 'Iqama') | list | first) -%}

{%- set staff_docs = frappe.get_all('Staff Documents', filters={'parent': staff_doc.name if staff_doc else ''}, fields=['document_type', 'document_no', 'expiry_date']) -%}
{%- set passport_doc = (staff_docs | selectattr('document_type', 'equalto', 'Passport') | list | first) -%}

{%- set vehicle_docs = frappe.get_all('Vehicle Documents', filters={'parent': doc.assigned_vehicle}, fields=['document_type', 'document_no', 'expiry_date']) -%}
{%- set istimara_doc = (vehicle_docs | selectattr('document_type', 'equalto', 'Istimara') | list | first) -%}
{%- set insurance_doc = (vehicle_docs | selectattr('document_type', 'equalto', 'Insurance') | list | first) -%}

{# ============================
  STYLING
============================= #}

<style>
@import url('https://fonts.googleapis.com/css2?family=Ubuntu:wght@300;400;700&family=Noto+Naskh+Arabic:wght@400;700&display=swap');

body {font-family:'Ubuntu',sans-serif;font-size:14px;}
.page {page-break-after:always;}
.header-section{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #ccc;padding-bottom:5px;}
.logo img{width:110px;}
.company-names{text-align:right;}
.company-names .en{font-size:16px;font-weight:bold;}
.company-names .ar{font-family:'Noto Naskh Arabic',serif;font-size:22px;direction:rtl;}
table{width:100%;border-collapse:collapse;margin-top:10px;}
th,td{border:1px solid #aaa;padding:6px;text-align:left;}
th{background:#efdfdf;color:#07417b;font-weight:800;}
.footer-section{border-top:1px solid #ccc;margin-top:20px;font-size:12px;padding-top:5px;color:#333;}
.page-tc-content{font-family:'Noto Naskh Arabic',serif;direction:rtl;font-size:13px;line-height:1.8;text-align:right;}
</style>

{# ============================
  PAGE 1 - TRIP SUMMARY
============================= #}

<div class="page">
  <div class="header-section">
    <div class="logo">
      {% if company.logo %}
        <img src="{{ company.logo }}">
      {% endif %}
    </div>
    <div class="company-names">
      <div class="en">{{ company.name or '' }}</div>
      <div class="ar">{{ company.company_name_arabic or '' }}</div>
    </div>
  </div>

  <table>
    <tbody>
      <tr>
        <th>Driver Name</th><td>{{ driver_doc.full_name or doc.driver }}</td>
        <th>Iqama No</th><td>{{ iqama_doc.document_no if iqama_doc else '-' }}</td>
      </tr>
      <tr>
        <th>License No</th><td>{{ license_doc.document_no if license_doc else '-' }}</td>
        <th>Passport No</th><td>{{ passport_doc.document_no if passport_doc else '-' }}</td>
      </tr>
      <tr>
        <th>Vehicle</th><td>{{ driver_doc.vehicle_type or '' }} ({{ doc.assigned_vehicle or '' }})</td>
        <th>Istimara No</th><td>{{ istimara_doc.document_no if istimara_doc else '-' }}</td>
      </tr>
      <tr>
        <th>Insurance</th><td>{{ insurance_doc.document_no if insurance_doc else '-' }}</td>
        <th>Date</th><td>{{ frappe.utils.formatdate(doc.date, 'dd-MM-yyyy') }}</td>
      </tr>
      <tr>
        <th>From</th><td>{{ doc.from_location }}</td>
        <th>To</th><td>{{ doc.to_location }}</td>
      </tr>
      <tr>
        <th>Departure</th><td>{{ doc.departure }}</td>
        <th>Arrival</th><td>{{ doc.arrival }}</td>
      </tr>
      <tr>
        <th>Distance</th><td>{{ doc.distance }} km</td>
        <th>Co-Driver</th><td>{{ doc.co_driver or '-' }}</td>
      </tr>
    </tbody>
  </table>

  <h4>Passengers</h4>
  <table>
    <thead>
      <tr>
        <th>#</th><th>Name</th><th>ID/Passport</th><th>Nationality</th><th>Contact</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.passengers %}
      <tr>
        <td>{{ loop.index }}</td>
        <td>{{ row.passenger_name }}</td>
        <td>{{ row.idpassport_no or '' }}</td>
        <td>{{ row.nationality or '' }}</td>
        <td>{{ row.contact_no or '' }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  {% if doc.qr_code %}
  <div style="text-align:center;margin-top:15px;">
    <img src="{{ doc.qr_code }}" width="120"><br>
    <small>Scan for Trip Details</small>
  </div>
  {% endif %}

  <div class="footer-section">
    CR: {{ cr_doc.document_no if cr_doc else '-' }} |
    Reg: {{ reg_doc.document_no if reg_doc else '-' }} |
    Phone: {{ company.phone or '' }}
  </div>
</div>

{# ============================
  PAGE 2 - CONTRACT (ARABIC)
============================= #}

<div class="page">
  <div class="header-section">
    <div class="logo">
      {% if company.logo %}
        <img src="{{ company.logo }}">
      {% endif %}
    </div>
    <div class="company-names">
      <div class="en">{{ company.name or '' }}</div>
      <div class="ar">{{ company.company_name_arabic or '' }}</div>
    </div>
  </div>

  <div class="page-tc-content">
    <p><strong>التاريخ الهجري:</strong> {{ doc.hijri_date or "_____" }} هـ</p>
    <p><strong>الميلادي:</strong> {{ frappe.utils.formatdate(doc.date, "dd-MM-yyyy") }} م</p>

    <h3 style="text-align:center;">عقد نقل ركاب بالحافلات</h3>
    <p>تم إبرام هذا العقد بين:</p>
    <p><strong>الطرف الأول :</strong> {{ company.company_name_arabic }}</p>
    <p><strong>الطرف الثاني :</strong>
      {% if doc.passengers and doc.passengers[0] %}
        {{ doc.passengers[0].passenger_name }}
      {% else %}
        ____________
      {% endif %}
    </p>

    <h3>بناءً على:</h3>
    <p>المادة (39) من اللائحة المنظمة لنشاط النقل البري للركاب وتوجيه الحافلات.</p>
    <p>المادة (1) من المادة (39) التي تنص على وجوب إبرام الناقل لعقد نقل مع الأطراف التجارية الأخرى.</p>

    <h3>اتفق الطرفان على ما يلي:</h3>
    <p><strong>موضوع العقد :</strong><br>
      يتعهد الطرف الأول بتنفيذ عملية نقل للطرف الثاني من {{ doc.from_location or "_____" }}
      إلى {{ doc.to_location or "_____" }}، مع مراقبة وتوجيه الركاب من الموقع المحدد مسبقًا وتوصيلهم إلى الوجهة.
    </p>

    <h3>سياسة الإلغاء والاستبدال:</h3>
    <p>في حالة إلغاء الحجز قبل موعد الرحلة بـ 24 ساعة، يتم استرداد المبلغ بالكامل.</p>
    <p>بعد هذا الموعد، لا يحق استرداد أي مبالغ.</p>
  </div>

  <div class="footer-section">
    CR: {{ cr_doc.document_no if cr_doc else '-' }} |
    Reg: {{ reg_doc.document_no if reg_doc else '-' }} |
    Phone: {{ company.phone or '' }}
  </div>
</div>
